def add(a, b):
    return a + b

def sub(a, b):
    return a - b

ops = {"+": add, "-": sub}
print(ops["+"](2, 3), ops["-"](5, 1))

def apply(func, x):
    return func(x)

print(apply(len, "привет"))

def show(*args, **kwargs):
    print(args, kwargs)

show(1, 2, a=3)
nums = [1, 2]
