def only_named(a, *, b):
    return a + b

print(only_named(1, b=2))

def compose(f, g):
    return lambda x: f(g(x))

clean = compose(str.strip, str.lower)
shout = compose(str.upper, str.strip)
print(repr(clean("  ПрИвЕт ")))
print(shout("  тихо  "))
